<student_code untrusted="true">
=== submission_08.ino ===
   1| // Lab 4 - toggle LED with a debounced button
   2| //
   3| // D2: button to ground. Configure as input and write HIGH to turn on
   4| //     the internal pull-up resistor, so it reads LOW when pressed.
   5| // D13: LED
   6| // Serial1: 9600 baud status messages
   7| 
   8| #define BTN_PIN      2
   9| #define LED_PIN      13
  10| #define DEBOUNCE_MS  5
  11| 
  12| bool lit = false;
  13| int lastSample = HIGH;
  14| int btnState = HIGH;
  15| unsigned long sampleChangedAt = 0;
  16| 
  17| void setup() {
  18|   pinMode(BTN_PIN, INPUT);
  19|   digitalWrite(BTN_PIN, HIGH);     // pull-up on
  20| 
  21|   pinMode(LED_PIN, OUTPUT);
  22|   digitalWrite(LED_PIN, LOW);
  23| 
  24|   Serial1.begin(9600);
  25| }
  26| 
  27| void loop() {
  28|   int sample = digitalRead(BTN_PIN);
  29| 
  30|   if (sample != lastSample) {
  31|     sampleChangedAt = millis();
  32|     lastSample = sample;
  33|   }
  34| 
  35|   if (millis() - sampleChangedAt >= DEBOUNCE_MS && sample != btnState) {
  36|     btnState = sample;
  37|     if (btnState == LOW) {
  38|       lit = !lit;
  39|       digitalWrite(LED_PIN, lit ? HIGH : LOW);
  40|       Serial1.println(lit ? "ON" : "OFF");
  41|     }
  42|   }
  43| }
</student_code>
